function TokenBucket(capacity, refillPerSec){
  return { capacity:capacity, refillPerSec:refillPerSec, tokens:capacity, last:0 };
}
function tbRefill(b, now){
  if(now<=b.last) return b;
  var elapsed=(now-b.last)/1000;
  var added=elapsed*b.refillPerSec;
  var tokens=Math.min(b.capacity, b.tokens+added);
  return { capacity:b.capacity, refillPerSec:b.refillPerSec, tokens:tokens, last:now };
}
function tbConsume(b, n, now){
  var r=tbRefill(b, now);
  n=(n||1);
  if(r.tokens>=n){
    return { allowed:true, tokensLeft:r.tokens-n, retryAfterMs:0,
             state:{capacity:r.capacity,refillPerSec:r.refillPerSec,tokens:r.tokens-n,last:now} };
  }
  var deficit=n-r.tokens;
  var ms=Math.ceil(deficit/r.refillPerSec*1000);
  return { allowed:false, tokensLeft:r.tokens, retryAfterMs:ms, state:b };
}
function LeakyBucket(capacity, leakPerSec){
  return { capacity:capacity, leakPerSec:leakPerSec, water:0, last:0 };
}
function lbRefill(b, now){
  if(now<=b.last) return b;
  var elapsed=(now-b.last)/1000;
  var leaked=Math.min(b.water, elapsed*b.leakPerSec);
  return { capacity:b.capacity, leakPerSec:b.leakPerSec, water:b.water-leaked, last:now };
}
function lbConsume(b, n, now){
  var r=lbRefill(b, now);
  n=(n||1);
  if(r.water+n<=r.capacity){
    return { allowed:true, waterLeft:r.water+n, retryAfterMs:0,
             state:{capacity:r.capacity,leakPerSec:r.leakPerSec,water:r.water+n,last:now} };
  }
  var need=n-(r.capacity-r.water);
  var ms=Math.ceil(need/r.leakPerSec*1000);
  return { allowed:false, waterLeft:r.water, retryAfterMs:ms, state:b };
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { TokenBucket:TokenBucket, tbRefill:tbRefill, tbConsume:tbConsume,
    LeakyBucket:LeakyBucket, lbRefill:lbRefill, lbConsume:lbConsume };
}
if (typeof window !== 'undefined') {
  window.RateForgePure = { TokenBucket:TokenBucket, tbRefill:tbRefill, tbConsume:tbConsume,
    LeakyBucket:LeakyBucket, lbRefill:lbRefill, lbConsume:lbConsume };
}
